  kie_command:    genMatch  ? genMatch[1].trim()  : '',
  raw_output:     raw,
};

fs.writeFileSync(vars.thumbnailPromptPath, JSON.stringify(pkg, null, 2));

console.log('Thumbnail prompt saved:', vars.thumbnailPromptPath);
if (pkg.text_overlay) console.log('Text overlay:', pkg.text_overlay);

return [{ json: {
  slug:                 vars.slug,
